63	export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
64	  const user = await currentUser();
65	  if (!user) redirect("/login");
66	  const imp = await impersonating();
67	
68	  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
69	  // admins impersonating a customer) always pass so they can keep working. This
70	  // only covers the dashboard tree — /login and /admin have their own layouts.
71	  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
72	    const message = await getSetting("maintenance_message");
73	    return (
74	      <main
75	        style={{
76	          minHeight: "100vh",
77	          display: "flex",
78	          flexDirection: "column",
79	          alignItems: "center",
80	          justifyContent: "center",
81	          gap: "1rem",
82	          padding: "2rem",
83	          textAlign: "center",
84	        }}
85	      >
86	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
87	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
88	      </main>
89	    );
90	  }
91	
92	  // Hide nav entries whose feature flag is disabled (secondary to the server-side
93	  // refusals in the order/create actions).
94	  const flags: Record<string, boolean> = {
95	    feature_game_servers: await getSettingBool("feature_game_servers", true),
96	    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
97	    feature_domains: await getSettingBool("feature_domains", true),
98	    feature_referrals: await getSettingBool("feature_referrals", true),
99	  };
100	  const visibleNav: NavSection[] = nav
101	    .map((section) => ({
102	      ...section,
103	      items: section.items.filter((item) => {
104	        const flag = FEATURE_HREF[item.href];
105	        return !flag || flags[flag];
106	      }),
107	    }))
108	    .filter((section) => section.items.length > 0);
109	
110	  const notifications = await db.notification.findMany({
111	    where: { userId: user.id },
112	    orderBy: { createdAt: "desc" },
113	    take: 15,
114	  });
115	
116	  // Support badge: this customer's own tickets awaiting a staff reply
117	  // (their newly opened tickets + threads where they replied last). Fails soft.
118	  const supportAwaiting = await db.ticket
119	    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
120	    .catch(() => 0);
121	  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
122	    ...section,
123	    items: section.items.map((item) =>
124	      item.href === "/dashboard/support" && supportAwaiting > 0
125	        ? { ...item, badge: supportAwaiting }
126	        : item
127	    ),
128	  }));
129	
130	  return (
131	    <Shell
132	      nav={navWithBadges}
133	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
134	      notifications={notifications.map((n) => ({
135	        id: n.id,
136	        title: n.title,
137	        body: n.body,
138	        href: n.href,
139	        readAt: n.readAt ? n.readAt.toISOString() : null,
140	        createdAt: n.createdAt.toISOString(),
141	      }))}
142	      impersonation={imp ? { adminName: imp.admin.name, targetEmail: imp.target.email } : null}
143	    >
144	      {/* Unverified accounts browse the whole portal freely; only buying is
145	          gated (lib/email-verification.ts). The prompt lives here rather than at
146	          checkout so the customer meets the prerequisite while it is cheap to
147	          fix, instead of meeting it with a card in their hand. Hidden while an
148	          admin is impersonating: it is not the admin's address to confirm, and
149	          the resend button would mail the customer from inside someone else's
150	          session. */}
151	      {!imp && !isEmailVerified(user) && !isGrandfathered(user) && (
152	        <UnverifiedEmailBanner email={user.email} />
153	      )}
154	      {children}
155	    </Shell>
156	  );
157	}
