3	import { useActionState, useEffect, useRef, useState, useTransition } from "react";
4	import { createTicket, replyTicket, setTicketStatus } from "@/lib/actions-support";
5	
6	export function NewTicketForm() {
7	  const [open, setOpen] = useState(false);
8	  const [state, action, pending] = useActionState(createTicket, {});
9	  // CONTROLLED, deliberately. React 19 resets uncontrolled inputs on every
10	  // `<form action={fn}>` submit, so a rejected ticket came back with the subject
11	  // and the body — up to 10,000 characters — blank. The person retyping it is by
12	  // definition someone who already has a problem and has just been told "no".
13	  //
14	  // This is the same reset that permanently locked customers out of 2FA login
15	  // (see components/AuthForms.tsx). There the cost was the account; here it is
16	  // the customer's own words, which they will not write twice.
17	  const [subject, setSubject] = useState("");
18	  const [priority, setPriority] = useState("NORMAL");
19	  const [body, setBody] = useState("");
20	
21	  return (
22	    <div>
23	      <div className="flex justify-end">
24	        <button className={open ? "btn-secondary" : "btn-primary"} onClick={() => setOpen((o) => !o)}>
25	          {open ? "Cancel" : "+ New ticket"}
26	        </button>
27	      </div>
28	      {open && (
29	        <form action={action} className="card mt-4 animate-fade-up space-y-4">
30	          {state?.error && (
31	            <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
32	              {state.error}
33	            </div>
34	          )}
35	          <div className="grid gap-4 sm:grid-cols-[1fr_180px]">
36	            <div>
37	              <label className="label">Subject</label>
38	              <input
39	                className="input"
40	                name="subject"
41	                required
42	                minLength={3}
43	                maxLength={150}
44	                value={subject}
45	                onChange={(e) => setSubject(e.target.value)}
46	                placeholder="Briefly, what's going on?"
47	              />
48	            </div>
49	            <div>
50	              <label className="label">Priority</label>
51	              <select className="input" name="priority" value={priority} onChange={(e) => setPriority(e.target.value)}>
52	                <option value="LOW">Low</option>
53	                <option value="NORMAL">Normal</option>
54	                <option value="HIGH">High</option>
55	                <option value="URGENT">Urgent</option>
56	              </select>
57	            </div>
58	          </div>
59	          <div>
60	            <label className="label">Message</label>
61	            <textarea
62	              className="input min-h-32 resize-y"
63	              name="body"
64	              required
65	              minLength={5}
66	              maxLength={10000}
67	              value={body}
68	              onChange={(e) => setBody(e.target.value)}
69	              placeholder="Include the server hostname and any error messages — the more detail, the faster we can help."
70	            />
71	          </div>
72	          <div className="flex justify-end">
73	            <button className="btn-primary px-6" disabled={pending}>
74	              {pending ? "Opening…" : "Open ticket"}
75	            </button>
76	          </div>
77	        </form>
78	      )}
79	    </div>
80	  );
81	}
