44	function fmtUptime(seconds: number): string {
45	  if (!seconds || seconds <= 0) return "—";
46	  const d = Math.floor(seconds / 86400);
47	  const h = Math.floor((seconds % 86400) / 3600);
48	  const m = Math.floor((seconds % 3600) / 60);
49	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
50	}
