     1	"use server";
     2	
     3	import { revalidatePath } from "next/cache";
     4	import { randomBytes } from "node:crypto";
     5	import bcrypt from "bcryptjs";
     6	import { db } from "./db";
     7	import { requireUser, realUser } from "./auth";
     8	import { generateSecret, otpauthURL, verifyTOTP } from "./totp";
     9	import { encryptSecret } from "./crypto-box";
    10	import { hashCode, totpSecretOf, verifyTotpForUser } from "./totp-verify";
    11	
    12	// `totpSecretOf`, `hashCode` and `verifyTotpForUser` live in the PLAIN module
    13	// `./totp-verify`. They must not be exported from this file: everything exported
    14	// from a `"use server"` module becomes a network-callable server action, and
    15	// `verifyTotpForUser` takes a caller-supplied userId with no auth and no rate
    16	// limit — as an action it was an unauthenticated 2FA brute-force oracle that
    17	// bypassed login()'s throttle entirely. See lib/totp-verify.ts.
    18	
    19	/**
    20	 * Two-factor authentication (TOTP) server actions.
    21	 *
    22	 * Enrolment flow:
    23	 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
    24	 *      stays false), and returns the otpauth URI + secret for the UI to show.
    25	 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
    26	 *      success `totpEnabled` flips true and backup codes are generated.
    27	 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
    28	 *      the account password.
    29	 *
    30	 * Backup codes are one-time; only their sha256 hashes are stored.
    31	 */
    32	
    33	
    34	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
    35	function makeBackupCodes(n = 10): string[] {
    36	  return Array.from({ length: n }, () => {
    37	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
    38	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
    39	  });
    40	}
    41	
    42	/**
    43	 * Step 1: create (but do not yet activate) a TOTP secret.
    44	 *
    45	 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
    46	 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
    47	 * optional `error` is populated when enrolment is refused.
    48	 */
    49	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
    50	  const user = await requireUser();
    51	
    52	  // Block enrolment while impersonating: the real acting account must be the
    53	  // same account being enrolled, so an admin can't seed a customer's 2FA.
    54	  const real = await realUser();
    55	  if (!real || real.id !== user.id) {
    56	    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
    57	  }
    58	
    59	  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
    60	  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
    61	  if (user.totpEnabled === true) {
    62	    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
    63	  }
    64	
    65	  const secret = generateSecret();
    66	  // Store encrypted at rest; clear any legacy plaintext value for this account.
    67	  await db.user.update({
    68	    where: { id: user.id },
    69	    data: { totpSecretEnc: encryptSecret(secret), totpSecret: null, totpEnabled: false },
    70	  });
    71	  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
    72	}
    73	
    74	/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
    75	export async function confirmTotpEnrollment(
    76	  prev: unknown,
    77	  formData: FormData,
    78	): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
    79	  const user = await requireUser();
    80	  const code = String(formData.get("code") ?? "");
    81	  const secret = totpSecretOf(user);
    82	  if (!secret) return { error: "Start enrolment first." };
    83	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect. Try again." };
    84	
    85	  const backupCodes = makeBackupCodes();
    86	  await db.user.update({
    87	    where: { id: user.id },
    88	    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
    89	  });
    90	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
    91	  revalidatePath("/dashboard/settings");
    92	  return { ok: true, backupCodes };
    93	}
    94	
    95	/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
    96	export async function regenerateBackupCodes(
    97	  prev: unknown,
    98	  formData: FormData,
    99	): Promise<{ error?: string; backupCodes?: string[] }> {
   100	  const user = await requireUser();
   101	  const code = String(formData.get("code") ?? "");
   102	  const secret = totpSecretOf(user);
   103	  if (!user.totpEnabled || !secret) return { error: "2FA is not enabled." };
   104	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect." };
   105	  const backupCodes = makeBackupCodes();
   106	  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
   107	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
   108	  return { backupCodes };
   109	}
   110	
   111	/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
   112	export async function disableTotp(
   113	  prev: unknown,
   114	  formData: FormData,
   115	): Promise<{ error?: string; ok?: boolean }> {
   116	  const user = await requireUser();
   117	  const proof = String(formData.get("proof") ?? "");
   118	  if (!user.totpEnabled) return { error: "2FA is not enabled." };
   119	
   120	  const secret = totpSecretOf(user);
   121	  const codeValid =
   122	    (secret ? verifyTOTP(secret, proof) : false) ||
   123	    (await verifyTotpForUser(user.id, proof));
   124	  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
   125	  if (!codeValid && !passwordValid) {
   126	    return { error: "Enter a valid authenticator code, backup code, or your password." };
   127	  }
   128	
   129	  await db.user.update({
   130	    where: { id: user.id },
   131	    data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [] },
   132	  });
   133	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
   134	  revalidatePath("/dashboard/settings");
   135	  return { ok: true };
   136	}

