221	}) {
222	  const pathname = usePathname();
223	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
224	  // main so they fill the entire content area under the header with no gap.
225	  const fullBleed = pathname === "/dashboard/mail" || pathname === "/dashboard/calendar";
226	  const [notifOpen, setNotifOpen] = useState(false);
227	  const [sidebarOpen, setSidebarOpen] = useState(false);
228	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
229	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
230	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
231	  const [collapsed, setCollapsed] = useState(false);
232	  const [, startTransition] = useTransition();
233	
234	  useEffect(() => {
235	    try {
236	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
237	    } catch {}
238	  }, []);
239	  function toggleCollapsed() {
240	    setCollapsed((c) => {
241	      const next = !c;
242	      try {
243	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
244	      } catch {}
245	      return next;
246	    });
247	  }
248	
249	  /**
250	   * Publish the rail's current width so `position: fixed` chrome outside this
251	   * subtree can sit beside it instead of guessing.
252	   *
253	   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
254	   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
255	   * whenever a customer collapsed the sidebar. A CSS variable on the document
256	   * element reaches the dock regardless of where it is mounted.
257	   */
258	  useEffect(() => {
259	    document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
260	  }, [collapsed]);
261	
262	  /**
263	   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
264	   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
265	   * page sidebar and must never be hidden or inerted.
266	   *
267	   * Starts `true` (desktop) so the server render and the first client render
268	   * agree, and so a JS-less or pre-hydration page never has its navigation
269	   * inerted. The listener corrects it a tick later.
270	   */
271	  const [isDesktopRail, setIsDesktopRail] = useState(true);
272	  useEffect(() => {
273	    const mq = window.matchMedia("(min-width: 1024px)");
274	    const sync = () => setIsDesktopRail(mq.matches);
275	    sync();
276	    mq.addEventListener("change", sync);
277	    return () => mq.removeEventListener("change", sync);
278	  }, []);
279	  /**
280	   * Closed, off-canvas and out of reach. The rehearsal found the closed drawer
281	   * still `visibility: visible` with no `aria-hidden` and **25 focusable
282	   * descendants in the tab order** — so a keyboard user on a phone tabbed
283	   * through the entire hidden navigation before reaching the page.
284	   */
285	  const drawerHidden = !isDesktopRail && !sidebarOpen;
286	
287	  // Escape closes the drawer. It did nothing at all before: the drawer had no
288	  // close button either (the only in-drawer button is the collapse toggle, which
289	  // is `lg:flex`), so a backdrop tap was the single way out.
290	  useEffect(() => {
291	    if (!sidebarOpen) return;
292	    const onKey = (e: KeyboardEvent) => {
293	      if (e.key === "Escape") setSidebarOpen(false);
294	    };
295	    window.addEventListener("keydown", onKey);
296	    return () => window.removeEventListener("keydown", onKey);
297	  }, [sidebarOpen]);
298	
299	  // Navigating from a drawer link must close the drawer — otherwise the new page
300	  // renders behind a panel the customer has to dismiss by hand.
301	  useEffect(() => {
302	    setSidebarOpen(false);
303	  }, [pathname]);
304	
305	  const unread = notifications.filter((n) => !n.readAt).length;
306	
307	  // Flatten for the command palette: every sidebar entry plus every secondary
308	  // destination hidden behind it, so ⌘K still reaches all ~41 admin routes even
309	  // though only 14 of them have a sidebar row. The child sharing the entry's own
310	  // href is skipped so the landing page isn't listed twice. Flat items (customer
311	  // portal) pass through unchanged.
312	  const flatNav = nav.flatMap((s) =>
313	    s.items.flatMap((i) => [
314	      { label: i.label, href: i.href, section: s.label },
315	      ...(i.children ?? [])
316	        .filter((c) => c.href !== i.href)
317	        .map((c) => ({ label: c.label, href: c.href, section: s.label })),
318	    ])
319	  );
320	
321	  return (
322	    // The terminal dock lives at the shell level so a shell session survives
323	    // in-portal navigation: App Router keeps Shell mounted across page changes,
324	    // so the dock (and its live sockets) is never unmounted. The provider is
325	    // inert until a page calls useTerminalDock().openSession(...).
326	    <TerminalDockProvider>
327	    <div className="flex min-h-screen">
328	      <CommandPalette nav={flatNav} />
329	      <FeedbackWidget />
330	      <VisitTracker kind="portal" />
331	
332	      {/* Sidebar */}
333	      <aside
334	        id="portal-sidebar"
335	        // `lg:sticky lg:top-0 lg:h-screen`, NOT `lg:static`: static put the rail in
336	        // normal document flow, so on desktop it scrolled away with the page and
337	        // navigation disappeared on any long view. Sticky keeps it in flow (main
338	        // content still sits beside it, no overlap) while pinning it to the
339	        // viewport. The <nav> inside already has flex-1 + overflow-y-auto, so a
340	        // long menu scrolls within the rail rather than pushing it off-screen.
341	        className={`fixed inset-y-0 left-0 z-40 flex w-60 flex-col border-r border-white/[0.06] bg-navy-900/80 backdrop-blur-xl transition-all lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${
342	          collapsed ? "lg:w-[4.75rem]" : "lg:w-60"
343	        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
344	        // Off-canvas and closed on a phone: out of the tab order and out of the
345	        // accessibility tree. `-translate-x-full` alone hides it from eyes only —
346	        // 25 links behind it stayed focusable.
347	        inert={drawerHidden}
