    14	export async function updateNotificationPrefs(
    15	  prev: unknown,
    16	  formData: FormData,
    17	): Promise<{ ok?: boolean; error?: string; note?: string }> {
    18	  const user = await requireUser();
    19	  const prefs: NotificationPrefs = {
    20	    email: formData.get("email") === "on",
    21	    product: formData.get("product") === "on",
    22	    // Pinned true — see `NotificationPrefs.security`. Security, password and 2FA
    23	    // messages are CRITICAL and must never be suppressible, so there is no
    24	    // toggle for them and nothing may store a withdrawal of consent for them.
    25	    security: true,
    26	  };
    27	  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });
    28	
    29	  // Make "Product updates" real TODAY, not once someone else wires it.
    30	  //
    31	  // Campaigns are addressed from `NewsletterSubscriber` BY EMAIL ADDRESS
    32	  // (lib/actions-newsletter-campaign.ts) — a table with no relation to `User` —
    33	  // so storing `product: false` on the user suppresses precisely nothing. That
    34	  // was the P1-32 failure at its worst: the customer withdraws marketing consent,
    35	  // sees "Saved ✓", and the next campaign still lands in their inbox. For a
    36	  // UK/EU customer that is a consent obligation, not a UX nicety.
    37	  //
    38	  // Deliberately one-way: turning the toggle ON does NOT subscribe them. This
    39	  // form posts every checkbox on every save and `product` defaults to ticked, so
    40	  // auto-subscribing would add customers to a marketing list as a side effect of
    41	  // saving an unrelated preference. A toggle may withdraw consent; it must never
    42	  // manufacture it.
    43	  let note: string | undefined;
    44	  if (!prefs.product) {
    45	    const removed = await db.newsletterSubscriber.deleteMany({
    46	      where: { email: user.email.toLowerCase() },
    47	    });
    48	    if (removed.count > 0) note = "Removed from the product-news list.";
    49	  }
    50	
    51	  revalidatePath("/dashboard/settings");
    52	  return { ok: true, note };
