import { chromium } from "/root/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs";
import { readFileSync } from "node:fs";

const BASE = process.argv[2] || "http://127.0.0.1:3000";
const CREDS = process.argv[3] || "/root/nxeon-credentials.txt";
const txt = readFileSync(CREDS, "utf8");
const email = /Email:\s*(\S+)/.exec(txt)[1];
const password = /Password:\s*(\S+)/.exec(txt)[1];

const ROUTES = [
  "/dashboard",
  "/dashboard/servers",
  "/dashboard/billing",
  "/dashboard/invoices",
  "/dashboard/settings",
  "/dashboard/support",
  "/dashboard/deploy",
  "/dashboard/projects",
  "/dashboard/activity",
  "/dashboard/volumes",
  "/dashboard/ssl",
  "/dashboard/domains",
  "/dashboard/team",
  "/dashboard/refer",
  "/dashboard/feedback",
  "/dashboard/games",
  "/dashboard/migrate",
  "/dashboard/email",
  "/dashboard/calendar",
  "/dashboard/claude-code",
  "/dashboard/build",
  "/dashboard/affiliate",
];

const browser = await chromium.launch();
const ctx = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
});
const page = await ctx.newPage();
const errs = [];
page.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));

console.log("### LOGIN", BASE);
await page.goto(BASE + "/login", { waitUntil: "domcontentloaded" });
await page.fill('input[name="email"]', email);
await page.fill('input[name="password"]', password);
await Promise.all([
  page.waitForURL(/dashboard|login/, { timeout: 30000 }).catch(() => {}),
  page.click('button[type="submit"], form button'),
]);
await page.waitForTimeout(2500);
console.log("after login:", page.url());

console.log("\n### 390px HORIZONTAL OVERFLOW");
const serverLinks = [];
for (const r of ROUTES) {
  try {
    const resp = await page.goto(BASE + r, { waitUntil: "domcontentloaded", timeout: 45000 });
    await page.waitForTimeout(700);
    const m = await page.evaluate(() => ({
      sw: document.documentElement.scrollWidth,
      cw: document.documentElement.clientWidth,
      bodySW: document.body.scrollWidth,
    }));
    window0 = await page.evaluate(() => {
      window.scrollTo(9999, 0);
      const x = window.scrollX;
      window.scrollTo(0, 0);
      return x;
    });
    const bad = m.sw > m.cw + 1;
    console.log(
      `${bad ? "OVERFLOW" : "ok      "} ${r.padEnd(28)} status=${resp?.status()} scrollWidth=${m.sw} client=${m.cw} scrollX=${window0}`
    );
    if (r === "/dashboard/servers" || r === "/dashboard") {
      const hrefs = await page.$$eval('a[href^="/dashboard/servers/"]', (as) => as.map((a) => a.getAttribute("href")));
      for (const h of hrefs) if (!serverLinks.includes(h)) serverLinks.push(h);
    }
  } catch (e) {
    console.log(`ERROR    ${r.padEnd(28)} ${String(e).slice(0, 120)}`);
  }
}

for (const h of serverLinks.slice(0, 2)) {
  try {
    const resp = await page.goto(BASE + h, { waitUntil: "domcontentloaded", timeout: 45000 });
    await page.waitForTimeout(1200);
    const m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }));
    console.log(`${m.sw > m.cw + 1 ? "OVERFLOW" : "ok      "} ${h.padEnd(28)} status=${resp?.status()} scrollWidth=${m.sw} client=${m.cw}`);
  } catch (e) {
    console.log(`ERROR ${h} ${String(e).slice(0, 120)}`);
  }
}

console.log("\n### MOBILE DRAWER");
await page.goto(BASE + "/dashboard", { waitUntil: "domcontentloaded" });
await page.waitForTimeout(800);
const hb = await page.evaluate(() => {
  const b = document.querySelector("header button.lg\\:hidden");
  if (!b) return null;
  return { label: b.getAttribute("aria-label"), expanded: b.getAttribute("aria-expanded"), controls: b.getAttribute("aria-controls") };
});
console.log("hamburger:", JSON.stringify(hb));
const closedState = await page.evaluate(() => {
  const a = document.querySelector("#portal-sidebar");
  if (!a) return null;
  return {
    inert: a.hasAttribute("inert"),
    ariaHidden: a.getAttribute("aria-hidden"),
    focusable: a.querySelectorAll("a,button,input,select,textarea").length,
    x: a.getBoundingClientRect().x,
  };
});
console.log("sidebar closed:", JSON.stringify(closedState));
