import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { vpsTermPriceCents, vpsEffectiveMonthly, VPS_TERMS } from "../lib/billing-terms.ts";
import { currentPromo, promoPriceCents, LAUNCH_SALE, type Promo } from "../lib/promotions.ts";
import { extraDiskCentsAt } from "../lib/extra-disk.ts";
import { renewalQuote } from "../lib/renewal-quote.ts";

/**
 * REAL INCIDENT (2026-07-25, user report): "the price said 8.99 but it only
 * charged 6.29".
 *
 * The deploy wizard displayed the REGULAR term price while lib/order.ts charged
 * the promo-discounted first-term price. Root cause: the promo math existed
 * twice — `promoPriceCents` (lib/promotions.ts) on the server and a hand-rolled
 * copy in `components/customer/DeployWizard.tsx` — so "displayed === charged"
 * held only by coincidence. The audit's words: this class of bug "would have
 * been caught by one assertion that the wizard and engine agree".
 *
 * These tests pin the composed price across every plan price x every term x
 * promo-on/promo-off, and include a tripwire on the wizard's duplicated line so
 * that editing it forces a re-check against promoPriceCents.
 *
 * Deterministic: every promo lookup takes an injected date, never Date.now().
 */

/** Repo root, resolved from this file so the suite works from any cwd. */
const REPO = join(__dirname, "..");

/** The live plan catalogue at the time of the incident (cents/month). */
const PLAN_MONTHLY_CENTS = [899, 1299, 2099, 3299];

/** No-promo control: the same shape as a real promo with the discount switched off. */
const NO_PROMO: Promo = { ...LAUNCH_SALE, discountPercent: 0 };
/** The promo that was running when the $8.99/$6.29 mismatch was reported. */
const SUMMER_2026 = new Date("2026-07-26T12:00:00.000Z");

/**
 * What lib/order.ts orderQuote CHARGES (lib/order.ts:135-140):
 * regular term price -> promo on the first term -> add-ons at full price.
 */
function chargedCents(monthlyCents: number, months: number, promo: Promo, addonMonthlyCents = 0): number {
  const regularPlanCents = vpsTermPriceCents(monthlyCents, months);
  return promoPriceCents(regularPlanCents, promo) + addonMonthlyCents * months;
}

/**
 * What the wizard DISPLAYS. `wizardPromoCents` is that file's own line, reproduced
 * verbatim because the component re-implements promoPriceCents instead of
 * importing it.
 */
const wizardPromoCents = (regular: number, promoPercent: number) => Math.round(regular * (1 - promoPercent / 100));

/**
 * The REGULAR (renewal) total for a term, as the wizard now derives it:
 * `renewalQuote()` — the same function the server page quotes "Renew now" from and
 * lib/actions.ts renewNow charges through. The wizard used to compute this itself
 * with vpsTermPriceCents; see the H1 test below for why that mattered.
 */
function displayedRegularCents(monthlyCents: number, months: number, addonMonthlyCents = 0): number {
  // `extraDiskPerGbCents` is expressed per GB, so 1 GB at the add-on rate models
  // the same monthly surcharge the old signature took directly.
  return renewalQuote(
    {
      termMonths: months,
      extraDiskGB: addonMonthlyCents > 0 ? 1 : 0,
      plan: { name: "Plan", priceCents: monthlyCents },
      gamePlan: null,
      dedicatedIp: null,
    },
    { ipMonthlyCents: 0, extraDiskPerGbCents: addonMonthlyCents },
  ).totalCents;
}

/**
 * What the wizard displays as "Due today" / the term card's first-term figure:
 * the promo applied to the plan portion of the regular total, add-ons back at full
 * price. The plan portion is the regular total MINUS the add-ons, not a second
 * derivation of the term price.

