 * Remove `//` and slash-star comments while preserving string and template
 * literals verbatim (a `"https://…"` is not a comment, and neither is the `//`
 * inside `/^https?:\/\//`). Replaces each comment with a single space so token
 * boundaries survive.
 */


function source(file: string): string {
  return stripComments(readFileSync(join(LIB, file), "utf8"));
}

