// lib/renewal-charge.ts.
const renewals = paidServers.map((s) => ({ server: s, charge: renewalCharge(s, prices) }));
// Monthly run-rate. Deliberately a division of the AUTHORITATIVE term total
// rather than a fresh sum of `plan.priceCents`: an annual server's monthly
// share is its real term price spread over the months it buys, and a game
// server contributes its game-plan price, not the VPS plan it is built on.
const monthlySpendCents = renewals.reduce(
  (sum, r) => sum + Math.round(r.charge.totalCents / Math.max(1, r.charge.months)),
