export function AddSshKeyForm() {
  const [state, action, pending] = useActionState(addSshKey, {});
  // CONTROLLED, deliberately — the same reason components/customer/TicketForms.tsx
  // is. React 19 resets uncontrolled fields on every `<form action={fn}>` submit,
  // and the one error this form can return is
  // `"Not a valid OpenSSH public key"` (lib/actions-account.ts:54). So the field
  // was blanked at precisely the moment the customer needs the text back: a
  // multi-line key they pasted out of a terminal, rejected, gone. They then have
  // to go and `cat ~/.ssh/id_ed25519.pub` again to fix a typo they can no longer
  // see. Cleared only on a submit that came back without an error, watching the
  // pending edge because the action returns `{}` for success — indistinguishable
  // from its initial value.
  const [name, setName] = useState("");
  const [publicKey, setPublicKey] = useState("");
  const wasPending = useRef(false);
  useEffect(() => {
    if (wasPending.current && !pending && !state?.error) {
      setName("");
      setPublicKey("");
    }
    wasPending.current = pending;
  }, [pending, state]);

  return (
    <form action={action} className="space-y-4">
      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
      <div className="max-w-xs">
        <label className="label" htmlFor="ssh-key-name">
          Key name
        </label>
        <input
          id="ssh-key-name"
          className="input"
          name="name"
          required
          maxLength={60}
          placeholder="work-laptop"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
      </div>
      <div>
        <label className="label" htmlFor="ssh-key-body">
          Public key
        </label>
        <textarea
          id="ssh-key-body"
          className="input min-h-24 resize-y font-mono text-xs"
          name="publicKey"
          required
          placeholder="ssh-ed25519 AAAAC3NzaC1lZDI1NTE5… user@host"
          value={publicKey}
          onChange={(e) => setPublicKey(e.target.value)}
        />
        <p className="mt-1 text-xs text-slate-500">
          The contents of <code className="font-mono text-brand-200">~/.ssh/id_ed25519.pub</code> —
          the public half, one line, starting <code className="font-mono text-brand-200">ssh-</code>.
          Never paste a private key.
        </p>
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Adding…" : "Add SSH key"}
      </button>
    </form>
  );
}

